#!/bin/bash
set -euo pipefail
# 本 recipe 的生成命令（由 conan_packager.py gen 自动记录）。
#
# 重生成时**照这个改**，别凭 conanfile.py 反推参数：漏一个 flag 就静默少一项能力，
# 而且往往是构建装包全绿、下游才炸（graphviz 漏了 --post-install-cmd "bin/dot -c"，
# 插件索引 config8 不再生成，dlopen 全失效）。
#
# --out/--src 未记录（本地绝对路径），跑的时候自己补。
python3 <conan_packager.py 的路径> gen --name poppler --version 25.12.0.2 --build-system cmake --cmake-toolchain conan --test-lang cpp --sign-so --pkgconfig-deps --pkgconfig-name poppler-glib --libs poppler,poppler-glib,poppler-cpp --source-url https://poppler.freedesktop.org/poppler-25.12.0.tar.xz --cli-tool 'PDF 命令行工具集（pdfinfo 读元信息、pdftotext 抽文本、pdftocairo/pdftoppm 转图片）' --homepage https://poppler.freedesktop.org/ --sha256 c18b40eb36b1a0c5b86e29ca054bf0770304583da4f2cdd42fe86eca6a20de48 --requires freetype/2.14.3,fontconfig/2.18.1,cairo/1.18.4,glib/2.84.0.1,zlib/1.3.1.1,libjpeg-turbo/3.2.0,libpng/1.6.58,libtiff/4.7.2,lcms2/2.19,openjpeg/2.5.4,boost/1.90.0.3 --include-dirs include,include/poppler,include/poppler/glib,include/poppler/cpp --inject-dep-includes --inject-dep-libdirs --prefer-upstream-find Cairo --prefer-upstream-find GLIB --prefer-upstream-find LCMS2 --cmake-def CMAKE_CXX_FLAGS=-fexperimental-library --cmake-def ENABLE_GLIB=ON --cmake-def ENABLE_CPP=ON --cmake-def ENABLE_UTILS=ON --cmake-def ENABLE_LIBTIFF=ON --cmake-def ENABLE_LCMS=ON --cmake-def ENABLE_BOOST=ON --cmake-def ENABLE_LIBOPENJPEG=openjpeg2 --cmake-def OPENJPEG_MAJOR_VERSION=2 --cmake-def 'CAIRO_INCLUDE_DIRS={cairo:includedir}/cairo' --cmake-def 'CAIRO_LIBRARIES={cairo:libdir}/libcairo.so' --cmake-def 'GLIB2_MKENUMS={glib:pkg}/bin/glib-mkenums' --cmake-def 'LCMS2_INCLUDE_DIR={lcms2:includedir}' --cmake-def 'LCMS2_LIBRARIES={lcms2:libdir}/liblcms2.so' --cmake-def ENABLE_UNSTABLE_API_ABI_HEADERS=ON --cmake-def ENABLE_QT5=OFF --cmake-def ENABLE_QT6=OFF --cmake-def ENABLE_NSS3=OFF --cmake-def ENABLE_LIBCURL=OFF --cmake-def ENABLE_GPGME=OFF --cmake-def ENABLE_PGP_SIGNATURES=OFF --cmake-def ENABLE_GOBJECT_INTROSPECTION=OFF --cmake-def ENABLE_GTK_DOC=OFF --cmake-def BUILD_GTK_TESTS=OFF --cmake-def BUILD_QT5_TESTS=OFF --cmake-def BUILD_QT6_TESTS=OFF --cmake-def BUILD_CPP_TESTS=OFF --cmake-def BUILD_MANUAL_TESTS=OFF --out <输出根目录>
